const D=window.DATA,$=id=>document.getElementById(id),money=x=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(x/100),pct=x=>x==null?'—':(100*x).toFixed(1)+'%',monthName=s=>new Date(s+'T12:00:00').toLocaleDateString('en-US',{month:'short',year:'numeric'});let idx=D.months.length-1;
D.months.forEach((b,i)=>$('month').add(new Option(monthName(b.month),i,i===idx,i===idx)));
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button,.section').forEach(x=>x.classList.remove('active'));b.classList.add('active');$(b.dataset.tab).classList.add('active')});
const svg=(content,w=700,h=280)=>`<svg role="img" viewBox="0 0 ${w} ${h}" xmlns="http://www.w3.org/2000/svg">${content}</svg>`;
function lines(series,max,labels,percent=false){let w=700,h=270,l=55,r=20,t=20,bot=38;let xp=i=>percent?l+parseFloat(labels[i])/parseFloat(labels[labels.length-1])*(w-l-r):l+i*(w-l-r)/(labels.length-1);let s='';for(let i=0;i<=4;i++){let y=t+(h-t-bot)*i/4;s+=`<line x1="${l}" x2="${w-r}" y1="${y}" y2="${y}" stroke="#e6ece7"/><text x="${l-8}" y="${y+4}" text-anchor="end">${percent?Math.round((max-max*i/4)*100)+'%':'$'+Math.round((max-max*i/4)/100000)+'k'}</text>`}series.forEach(a=>{let pts=a.values.map((v,i)=>`${xp(i)},${t+(1-v/max)*(h-t-bot)}`).join(' ');s+=`<polyline points="${pts}" fill="none" stroke="${a.color}" stroke-width="2.5"/>`});labels.forEach((x,i)=>{if(labels.length<10||i%6===0||i===labels.length-1)s+=`<text x="${xp(i)}" y="${h-10}" text-anchor="middle">${x}</text>`});return svg(s,w,h)}
function waterfall(b){let vals=[b.opening,b.new_mrr,b.reactivation,b.expansion,-b.contraction,-b.churn,b.closing],labels=['Opening','New','Reactivate','Expansion','Contraction','Churn','Closing'];let max=Math.max(b.opening+b.new_mrr+b.reactivation+b.expansion,b.closing)*1.18||1,y=v=>235-v/max*195,s='',running=0;vals.forEach((v,i)=>{let from=i===0||i===6?0:running,to=i===0||i===6?v:running+v,x=25+i*95,top=y(Math.max(from,to)),bottom=y(Math.min(from,to));s+=`<rect x="${x}" y="${top}" width="66" height="${Math.max(bottom-top,1)}" rx="3" fill="${i===0||i===6?'#24463f':v>=0?'#77a697':'#c77b6c'}"><title>${labels[i]}: ${money(v)}</title></rect><text x="${x+33}" y="${top-10}" text-anchor="middle">${v<0?'−':''}${money(Math.abs(v))}</text><text x="${x+33}" y="260" text-anchor="middle">${labels[i]}</text>`;running=to});return svg(s,700,280)}
function table(headers,rows){return `<table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table>`}
function render(){const b=D.months[idx],prev=D.months[idx-1];$('kpis').innerHTML=[['Closing MRR',money(b.closing),`${b.opening?pct((b.closing-b.opening)/b.opening):'—'} vs opening`,b.closing<b.opening?'negative':'positive'],['New paying customers',String(D.months[idx].new_mrr?newPayers(idx):0),`${b.trial_starts} signups / trials`,''],['Net revenue retention',pct(b.nrr),'Excludes new and reactivated payers',b.nrr<1?'negative':'positive'],['Gross revenue retention',pct(b.grr),'Opening cohort before expansion','']].map(([l,v,s,c])=>`<div class="card"><div class="label">${l}</div><div class="value num ${c}">${v}</div><div class="sub">${s}</div></div>`).join('');
let loss=b.churn+b.contraction,gain=b.new_mrr+b.reactivation+b.expansion; $('insight').innerHTML=`<strong>${loss>gain?'Losses outweigh growth by '+money(loss-gain)+'.':'Growth exceeds losses by '+money(gain-loss)+'.'}</strong><p>${money(b.churn-b.involuntary)} voluntary cancellation MRR, ${money(b.involuntary)} payment-failure cancellation MRR, and ${money(b.contraction)} contraction versus ${money(gain)} from new, reactivated, and expanding customers.</p>`;
$('balanced').textContent=b.reconciliation_cents===0?'✓ Reconciled to $0':'Reconciliation error';$('waterfall').innerHTML=waterfall(b);let max=Math.max(...D.months.flatMap(x=>[x.closing,x.invoiced,x.cash]))*1.12;$('trend').innerHTML=lines([{values:D.months.map(x=>x.closing),color:'#14796c'},{values:D.months.map(x=>x.invoiced),color:'#acb8ae'},{values:D.months.map(x=>x.cash),color:'#54718c'}],max,D.months.map(x=>monthName(x.month)));$('planTable').innerHTML=table(['Plan','Opening payers','Customer churn','Revenue churn','Contraction'],D.plans.filter(p=>p.month===b.month).map(p=>[p.plan,p.opening_customers,pct(p.churned/p.opening_customers),pct(p.lost_mrr/p.opening_mrr),money(p.contraction)]));$('mrrDef').textContent=money(b.closing);$('invoiceDef').textContent=money(b.invoiced);$('cashDef').textContent=money(b.cash);scenario()}
function newPayers(i){return D.months[i].new_customers??'See CSV'}
function scenario(){let b=D.months[idx],v=+$('vol').value/100,p=+$('pay').value/100,u=+$('unc').value/100,vol=b.churn-b.involuntary,g=v*vol+p*b.involuntary,lo=Math.max(0,v-u)*vol+Math.max(0,p-u)*b.involuntary,hi=Math.min(1,v+u)*vol+Math.min(1,p+u)*b.involuntary;$('volLabel').textContent=pct(v);$('payLabel').textContent=pct(p);$('uncLabel').textContent=Math.round(u*100)+' percentage points';$('scenarioValue').textContent=money(b.closing+g);$('scenarioGain').textContent=money(g)+' MRR preserved vs '+money(b.closing)+' observed';$('scenarioRange').textContent='Assumption range: '+money(b.closing+lo)+' – '+money(b.closing+hi);}
$('month').onchange=()=>{idx=+$('month').value;render()};['vol','pay','unc'].forEach(id=>$(id).oninput=scenario);
$('retChart').innerHTML=lines([{values:D.retention.filter(x=>x.group==='True').map(x=>x.rate),color:'#14796c'},{values:D.retention.filter(x=>x.group==='False').map(x=>x.rate),color:'#b75042'}],1,D.retention.filter(x=>x.group==='True').map(x=>x.day+'d'),true);$('channelTable').innerHTML=table(['Channel','Eligible','Retained','95% interval'],D.channels.filter(x=>x.day===90).sort((a,b)=>b.rate-a.rate).map(x=>[x.group,x.n,pct(x.rate),pct(x.low)+'–'+pct(x.high)]));$('retTable').innerHTML=table(['Group','Horizon after day 30','Eligible','Still paying','Retention','95% interval'],D.retention.map(x=>[x.group==='True'?'Activated':'Not activated',x.day+' days',x.n,x.retained,pct(x.rate),pct(x.low)+'–'+pct(x.high)]));$('checkCount').textContent=Object.values(D.checks).filter(Boolean).length+' / '+Object.keys(D.checks).length+' validation checks passed';$('counts').textContent=Object.entries(D.counts).map(([t,n])=>n.toLocaleString()+' '+t.replaceAll('_',' ')).join(' · ');$('csvSelect').onchange=()=>{$('csvLink').href='downloads/'+$('csvSelect').value+'.csv'};render();
